import React, { useEffect, useState } from "react";
import { Button, Modal, ModalHeader, ModalBody, Form, FormGroup, ModalFooter, Input, Label } from 'reactstrap';
import axios from 'axios';

const UserList = () => {

    const [users, setUsers] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);
    const [userEdit, setUserEdit] = useState(null);
    const [isEdit, setIsEdit] = useState(false);
    const [modalDeleteOpen, setModalDeleteOpen] = useState(false);
    const [userDelete, setUserDelete] = useState(null);

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = () => {
        fetch('http://localhost/multimedios/Proyecto-grupal/API/users.php')
        .then(response => response.json())
        .then((dataResponse) => {
            setUsers(dataResponse);
        })
        .catch(error => {
            console.error('Error al ejecutar', error);
        });
    };

    const toggleModal = () => {
        setModalOpen(!modalOpen);
    };

    const toggleDeleteModal = (user) => {
        setUserDelete(user);
        setModalDeleteOpen(!modalDeleteOpen);
    };

    const toggleEditModal = (user) => {
        setUserEdit(user);
        if (user) {
            setIsEdit(true);
        } else {
            setIsEdit(false);
        }
        setModalOpen(true);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUserEdit({ ...userEdit, [name]: value });
    };

    // Función para guardar el usuario (crear o actualizar)
    const handleUserSave = async () => {
        try {
            const endpoint = isEdit ? 'updateUser.php' : 'createUser.php';
            const response = await axios.post(`http://localhost/multimedios/Proyecto-grupal/API/${endpoint}`, userEdit);
            console.log('Respuesta del API', response.data);
            toggleModal();
            fetchUsers();
        } catch (error) {
            console.error('Error en el API', error);
        }
    };

    const handleUserDelete = async () => {
        try {
            const response = await axios.post('http://localhost/multimedios/Proyecto-grupal/API/deleteUser.php', {
                idUser: userDelete.idUser
            });
            console.log('Respuesta del API', response.data);
            toggleDeleteModal();
            fetchUsers();
        } catch (error) {
            console.error('Error en el API', error);
        }
    };

    return (
        <div className="container">
            <br /><br /><br />
            <Button color="primary" onClick={() => toggleEditModal(null)}>Agregar Usuario</Button>

            <table className="table table-striped table-hover table-borderless table-primary align-middle">
                <thead className="thead-dark">
                    <tr>
                        <th>Id</th>
                        <th>Nombre</th>
                        <th>Email</th>
                        <th>Password</th>
                        <th>Fecha de Registro</th>
                        <th>Acciones</th>
                    </tr>
                </thead>
                <tbody className="table-group-divider">
                    {
                        users.map(
                            item => (
                                <tr key={item.idUser}>
                                    <td>{item.idUser}</td>
                                    <td>{item.name}</td>
                                    <td>{item.email}</td>
                                    <td>{item.password}</td>
                                    <td>{item.releaseDate}</td>
                                    <td>
                                        <Button color="info" onClick={() => toggleEditModal(item)}>Editar</Button>{' '}
                                        <Button color="danger" onClick={() => toggleDeleteModal(item)}>Eliminar</Button>
                                    </td>
                                </tr>
                            )
                        )
                    }
                </tbody>
            </table>

            <Modal isOpen={modalOpen} toggle={toggleModal}>
                <ModalHeader toggle={toggleModal}>{isEdit ? 'Editar Usuario' : 'Agregar Usuario'}</ModalHeader>
                <ModalBody>
                    <Form>
                        <FormGroup>
                            <Label for="name">Nombre</Label>
                            <Input type="text" name="name" id="name" value={userEdit?.name || ''} onChange={handleInputChange} />
                        </FormGroup>
                        <FormGroup>
                            <Label for="email">Email</Label>
                            <Input type="email" name="email" id="email" value={userEdit?.email || ''} onChange={handleInputChange} />
                        </FormGroup>
                        <FormGroup>
                            <Label for="password">Password</Label>
                            <Input type="password" name="password" id="password" value={userEdit?.password || ''} onChange={handleInputChange} />
                        </FormGroup>
                        <FormGroup>
                            <Label for="releaseDate">Fecha de Registro</Label>
                            <Input type="date" name="releaseDate" id="releaseDate" value={userEdit?.releaseDate || ''} onChange={handleInputChange} />
                        </FormGroup>
                    </Form>
                </ModalBody>
                <ModalFooter>
                    <Button color="primary" onClick={handleUserSave}>Guardar</Button>{' '}
                    <Button color="secondary" onClick={toggleModal}>Cancelar</Button>
                </ModalFooter>
            </Modal>

            <Modal isOpen={modalDeleteOpen} toggle={toggleDeleteModal}>
                <ModalHeader toggle={toggleModal}>Eliminar Usuario</ModalHeader>
                <ModalBody>
                    <p>¿Desea borrar el elemento?</p>
                </ModalBody>
                <ModalFooter>
                    <Button color="danger" onClick={handleUserDelete}>Borrar</Button>{' '}
                    <Button color="secondary" onClick={toggleDeleteModal}>Cancelar</Button>
                </ModalFooter>
            </Modal>
        </div>
    );
};

export default UserList;
